"use client";
import { useRef, useState } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { api } from "@/lib/api";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
export function VendorSubmissionForm(){
 const key=useRef<string|null>(null);const cache=useQueryClient();const [busy,setBusy]=useState(false);const [feedback,setFeedback]=useState("");
 const catalogue=useQuery({queryKey:["vendor-catalogue"],queryFn:()=>api.get<{id:string;testName:string;testCode:string;departmentId:string}[]>("/vendor-portal/catalogue")});
 const packages=useQuery({queryKey:["vendor-packages"],queryFn:()=>api.get<{id:string;name:string}[]>("/vendor-portal/packages")});
 const [packageSearch,setPackageSearch]=useState("");const [selectedPackage,setSelectedPackage]=useState("");
 const [departmentId,setDepartmentId]=useState("all");
 const departments=useQuery({queryKey:["vendor-departments"],queryFn:()=>api.get<{id:string;name:string}[]>("/vendor-portal/departments")});
 const doctors=useQuery({queryKey:["vendor-doctors"],queryFn:()=>api.get<{id:string;name:string}[]>("/vendor-portal/doctors")});
 return <form className="grid gap-3 sm:grid-cols-2" onSubmit={async event=>{event.preventDefault();if(busy)return;if(selectedPackage){setFeedback("A client-package tariff must be configured before this package can be submitted. Individual tests with configured client tariffs remain available.");return;}const form=event.currentTarget;const data=new FormData(form);key.current??=crypto.randomUUID();setBusy(true);setFeedback("");try{const result=await api.post<{billId:string;billNumber?:string}>("/vendor-portal/submissions",{requestKey:key.current,patient:{firstName:data.get("firstName"),lastName:data.get("lastName"),age:Number(data.get("age")),gender:data.get("gender"),mobile:data.get("mobile"),address:data.get("address")},order:{items:data.getAll("tests").map(testId=>({testId,quantity:1})),comments:data.get("comments"),referringDoctorId:data.get("referringDoctorId")||undefined}});setFeedback(`Submission saved. Reference ${result.billNumber??result.billId}.`);key.current=null;form.reset();await cache.invalidateQueries({queryKey:["vendor-bills"]});}catch(error){setFeedback(error instanceof Error?error.message:"Submission failed");}finally{setBusy(false);}}}>
 <label>First name<Input required minLength={2} maxLength={60} name="firstName"/></label><label>Last name<Input maxLength={60} name="lastName"/></label><label>Age (years)<Input required name="age" type="number" min={0} max={150}/></label><label>Gender<select name="gender" required className="block border p-2 w-full"><option value="female">Female</option><option value="male">Male</option><option value="other">Other</option></select></label><label>Mobile<Input required name="mobile" pattern="[0-9]{1,13}" maxLength={13}/></label><label>Address<Input name="address" maxLength={500}/></label>
 <label>Referring doctor<select name="referringDoctorId" className="block border p-2 w-full"><option value="">Self / not specified</option>{doctors.data?.map(doctor=><option key={doctor.id} value={doctor.id}>{doctor.name}</option>)}</select></label>{doctors.isError&&<p role="alert">Doctor list unavailable; reload to select a referring doctor.</p>}
 <label className="sm:col-span-2">Department<select aria-label="Department" className="block border p-2 w-full" value={departmentId} onChange={e=>setDepartmentId(e.target.value)}><option value="all">ALL</option>{departments.data?.map(row=><option key={row.id} value={row.id}>{row.name}</option>)}<option value="__packages">Packages/Profiles</option></select></label>{departments.isError&&<p role="alert">Department options unavailable. Reload to filter tests.</p>}<label className="sm:col-span-2">Requested tests<select aria-label="Requested tests" name="tests" multiple required={departmentId!=="__packages"} className="block border p-2 w-full h-32">{catalogue.data?.map(test=><option hidden={departmentId!=="all"&&departmentId!==test.departmentId} key={test.id} value={test.id}>{test.testCode} · {test.testName}</option>)}</select></label><fieldset className="sm:col-span-2 space-y-2"><legend>Packages/Profiles</legend><label>Search packages<Input value={packageSearch} onChange={e=>setPackageSearch(e.target.value)}/></label><label>Package<select aria-label="Package" className="block border p-2 w-full" value={selectedPackage} onChange={e=>setSelectedPackage(e.target.value)}><option value="">No package selected</option>{packages.data?.filter(row=>row.name.toLowerCase().includes(packageSearch.toLowerCase())).map(row=><option key={row.id} value={row.id}>{row.name}</option>)}</select></label><p className="text-sm">Package submission awaits a configured client-package tariff. No package prices are shown.</p>{packages.isError&&<p role="alert">Unable to load packages.</p>}</fieldset><label className="sm:col-span-2">Clinical / sample comments<Input name="comments" maxLength={500}/></label>{catalogue.isError&&<p role="alert">Unable to load available tests.</p>}<Button disabled={busy||catalogue.isPending||catalogue.isError}>{busy?"Submitting…":"Submit"}</Button>{feedback&&<p role="status">{feedback}</p>}
 </form>;
}
